const response = $input.item.json;
const requestedUrl = $node["Webhook"].json.url;

// Check if URL is accessible (2xx or 3xx status codes)
const statusCode = response.statusCode || 0;
const isValid = statusCode >= 200 && statusCode < 400;

let validationType = 'unknown';
let message = '';

if (statusCode === 0) {
  validationType = 'error';
  message = 'Unable to reach URL - connection timeout or network error';
} else if (statusCode >= 200 && statusCode < 300) {
  validationType = 'success';
  message = 'URL is accessible';
} else if (statusCode >= 300 && statusCode < 400) {
  validationType = 'redirect';
  message = 'URL redirects to another location';
} else if (statusCode === 404) {
  validationType = 'not_found';
  message = 'URL not found (404)';
} else if (statusCode === 403) {
  validationType = 'forbidden';
  message = 'Access forbidden (403)';
} else if (statusCode >= 400 && statusCode < 500) {
  validationType = 'client_error';
  message = `Client error (${statusCode})`;
} else if (statusCode >= 500) {
  validationType = 'server_error';
  message = `Server error (${statusCode})`;
}

return {
  url: requestedUrl,
  valid: isValid,
  statusCode: statusCode,
  validationType: validationType,
  message: message,
  contentType: response.headers?.['content-type'] || null,
  contentLength: response.headers?.['content-length'] || null
};
